content.content:
  color: var(--text-secondary);
  background: transparent;
  border: 1px dashed var(--border-subtle);
}

.add-printer:hover {
  background: var(--action-secondary-hover);
}

/* The gallery's scroller sits right beside the rail's divider, so a platform
   scrollbar reads as a second, heavier line. It is drawn as a thin subtle
   thumb over no track instead, leaving one divider on screen. */
.gallery,
.printer-column {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

.gallery::-webkit-scrollbar,
.printer-column::-webkit-scrollbar {
  width: 8px;
}

.gallery::-webkit-scrollbar-track,
.printer-column::-webkit-scrollbar-track {
  background: transparent;
}

/* Transparent at rest: the design draws one divider beside the rail, and a
   thumb sitting against it reads as a second heavier line. It appears when the
   pointer is over the surface it scrolls. */
.gallery::-webkit-scrollbar-thumb,
.printer-column::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: var(--radius-pill);
}

.gallery:hover::-webkit-scrollbar-thumb,
.printer-column:hover::-webkit-scrollbar-thumb {
  background: var(--border-subtle);
}

.gallery::-webkit-scrollbar-thumb:hover,
.printer-column::-webkit-scrollbar-thumb:hover {
  background: var(--border-strong);
}

/* Glyphs take the size and colour of the text beside them. */
.glyph {
  flex: 0 0 auto;
  width: var(--glyph-size);
  height: var(--glyph-size);
}

.printer-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.printer-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The header row ends in the status dot and the printer's actions menu. */
.printer-head-end {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

.printer-actions {
  position: relative;
  display: flex;
}

/* A quiet icon button: the menu is secondary to the card it sits on. */
.printer-menu-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--button-icon-width);
  height: var(--button-icon-height);
  padding: 0;
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  border-radius: var(--button-icon-radius);
  cursor: pointer;
}

.printer-menu-button .glyph {
  width: var(--button-icon-icon-size);
  height: var(--button-icon-icon-size);
}

.printer-menu-button:hover,
.printer-menu-button[aria-expanded='true'] {
  color: var(--text-primary);
  background: var(--action-secondary-hover);
}

.printer-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: var(--popover-row-gap);
  min-width: max-content;
  padding: var(--popover-padding-y) 0;
  background: var(--surface-raised);
  border: 1px solid var(--border-subtle);
  border-radius: var(--popover-radius);
  box-shadow: var(--elevation-medium);
}

.printer-menu button {
  display: flex;
  align-items: center;
  height: var(--menu-row-height);
  margin: 0 var(--menu-row-side-inset);
  padding: 0 12px;
  font: var(--font-body);
  color: var(--text-primary);
  text-align: left;
  white-space: nowrap;
  background: transparent;
