const [debugText, setDebugText] = useState('no click yet');
useEffect(() => {
  const describe = (event: PointerEvent | MouseEvent) => {
    const t = event.target as HTMLElement | null;
    const path = [];
    let node: HTMLElement | null = t;
    for (let i = 0; i < 6 && node; i++) {
      path.push(`${node.tagName}.${node.className || ''}#${node.id || ''}`);
      node = node.parentElement;
    }
    return `${event.type} x=${event.clientX} y=${event.clientY} target=${path.join(' < ')}`;
  };
  const onDown = (e: PointerEvent) => setDebugText((prev) => `DOWN: ${describe(e)}\n${prev}`.slice(0, 500));
  const onUp = (e: MouseEvent) => setDebugText((prev) => `CLICK: ${describe(e)}\n${prev}`.slice(0, 500));
  document.addEventListener('pointerdown', onDown, true);
  document.addEventListener('click', onUp, true);
  return () => {
    document.removeEventListener('pointerdown', onDown, true);
    document.removeEventListener('click', onUp, true);
  };
}, []);

