// The card header's kebab: Printer settings…, Rename, Remove printer…. A named
// printer's rename and removal are confirmed here; a device's open Orca's own
// dialogs, which confirm for themselves.
export function PrinterMenu({
  printer,
  otherNames,
  actions,
}: {
  printer: PrinterInfo;
  otherNames: string[];
  actions: PrinterActions;
}) {
  const [open, setOpen] = useState(false);
  const [dialog, setDialog] = useState<'rename' | 'remove' | null>(null);
  const [name, setName] = useState(printer.name);
  const root = useRef<HTMLDivElement>(null);
  const button = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const input = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open) return;
    root.current?.querySelector<HTMLButtonElement>('[role="menuitem"]:not(:disabled)')?.focus();
    const dismiss = (event: PointerEvent) => {
      const contained = !!root.current?.contains(event.target as Node);
      (window as unknown as { __debugLog?: (m: string) => void }).__debugLog?.(
        `dismiss contained=${contained} target=${(event.target as HTMLElement)?.tagName}.${(event.target as HTMLElement)?.className}`,
      );
      if (!contained) setOpen(false);
    };
    document.addEventListener('pointerdown', dismiss);
    return () => document.removeEventListener('pointerdown', dismiss);
  }, [open]);

  useEffect(() => {
    if (dialog === 'rename') {
      input.current?.focus();
      input.current?.select();
    }
    if (dialog === 'remove') panel.current?.querySelector<HTMLButtonElement>('button')?.focus();
  }, [dialog]);

  const closeDialog = () => {
    setDialog(null);
    button.current?.focus();
  };
  const named = printer.kind === 'named';
  const problem = renameProblem(name, printer.name, otherNames);

  const rename = () => {
    (window as unknown as { __debugLog?: (m: string) => void }).__debugLog?.('rename() called');
